from pathlib import Path
import json,hashlib,re
H=Path(__file__).resolve().parent
S=json.loads((H/'source.json').read_text());by={s['number']:s for s in S};out={};details={}
sha=lambda s:hashlib.sha256(s.encode()).hexdigest()
def put(n,body,reason,benefit,removed=None):
 s=by[n];r={k:s[k]for k in ['code_id','source_id','source_sha256','number']};r.update(status='rewrite_draft',proposed_xml=body,proposed_sha256=sha(body),reason=reason,benefit_review=benefit,current_beforeimage_sha256=s['current_beforeimage_sha256'],source_body_sha256=sha(s['source_xml']),source_notes_sha256=sha(s['source_notes_xml']))
 r['review_notes']='Corps source, notes DILA et avant-image éventuelle lus intégralement. Coordination de la réforme expresse du contrat unique : aucun nouveau terme d’emploi ni renouvellement CDD. Les contrats antérieurs et leurs créances restent régis par L1241-1 transitoire proposé dans le lot70, sous les suppressions expresses de formalités et sanctions. Les aides, dispenses et dérogations futures sont conservées dans leur champ propre. Aucun taux nouveau ni économie chiffrée n’est inventé. Ce candidat ne modifie ni le noyau de rupture rédigé par rewrite_travail ni les articles formation/intérim pris par le parent. Les renvois vers des périodes d’aide ou de mission ne valent pas terme de l’emploi. Contrôle final de concurrence requis ; aucun enregistrement par cet auteur.'
 if removed:r.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed)
 out[n]=r

def transition():return '<p>Les contrats conclus avant la réforme conservent leurs termes, créances et droits selon l’article L. 1241-1. La conversion en contrat unique conserve l’ancienneté et ne recommence pas l’essai. La durée d’une aide, d’un accompagnement ou d’une dérogation ne met pas fin, à elle seule, à la relation d’emploi.</p>'
# Branche : domaines autonomes et règle de hiérarchie en vigueur, aucun texte de priorité d’entreprise supposé.
b=by['L2253-1']['source_xml']
a='7° Les mesures relatives aux contrats de travail à durée déterminée et aux contrats de travail temporaire énoncées aux articles L. 1242-8, L. 1243-13, L. 1244-3, L. 1244-4, L. 1251-12, L. 1251-35, L. 1251-36 et L. 1251-37 du présent code ;'
c='7° Les mesures relatives aux contrats de travail temporaire énoncées aux articles L. 1251-12, L. 1251-35, L. 1251-36 et L. 1251-37, dans le champ qui leur demeure applicable. Pour les seuls contrats à durée déterminée conclus avant la réforme et maintenus par l’article L. 1241-1, les mesures prévues par l’ancienne rédaction des articles L. 1242-8, L. 1243-13, L. 1244-3 et L. 1244-4 conservent leur application transitoire ;'
assert a in b;b=b.replace(a,c)
b=b.replace('8° Les mesures relatives au contrat à durée indéterminée de chantier ou d\'opération énoncées aux articles L. 1223-8 et L. 1223-9 du présent code ;','8° Les mesures relatives aux contrats de chantier ou d’opération énoncées aux articles L. 1223-8 et L. 1223-9, pour les seules situations dans lesquelles leurs dispositions demeurent applicables, notamment à titre transitoire ;')
b=b.replace("10° Les conditions et les durées de renouvellement de la période d'essai mentionnées à l'article L. 1221-21 du code du travail ;",'10° Les conditions et durées de renouvellement d’un essai mentionnées à l’article L. 1221-21, pour les seuls essais antérieurs restant régis par ces dispositions ; ce renvoi ne permet pas de renouveler un essai du contrat unique lorsque ce renouvellement est interdit ;')
put('L2253-1',b,'Retire la compétence de branche sur les nouveaux CDD et borne les renvois de chantier/renouvellement d’essai à leur champ encore applicable. Conserve les autres domaines autonomes et la hiérarchie de branche en vigueur : aucune primauté d’entreprise non rédigée n’est inventée.','Les garanties de salaires minima, classifications, formation, protection complémentaire, égalité, transfert et travail temporaire restent dans leur champ. Les anciens CDD/essais et accords applicables gardent leurs garanties ; aucune compétence de branche ne rétablit un support supprimé.', ['Supprime la faculté de déterminer durées, renouvellements et carences pour de nouveaux CDD désormais interdits.'])
# Assurance chômage et données : suppression prospective des deux circuits de refus de CDI, aides/droits autonomes conservés.
b=by['L5422-1']['source_xml'];b=re.sub(r'<p>S\x27il est constaté.*?</p>','',b,flags=re.S);b+='<p>À compter de l’entrée en vigueur de la loi instituant le contrat unique, la restriction d’ouverture du droit liée aux deux refus de propositions de contrat à durée indéterminée prévue par l’ancienne rédaction du I cesse d’être opposable. Aucun nouveau signalement sur les fondements supprimés des articles L. 1243-11-1 et L. 1251-33-1 n’est requis. Les décisions antérieures, leurs recours et les restitutions légalement ouvertes demeurent régis par leurs règles propres ; aucun nouveau refus ou retrait d’allocation ne peut être fondé sur cette restriction abrogée.</p>'
put('L5422-1',b,'Supprime la restriction et les signalements particuliers de deux refus de CDI, devenus sans objet avec le contrat unique ; préserve les autres conditions d’ouverture, la rupture conventionnelle et la reconversion volontaire.','Les droits restent ouverts aux personnes éligibles selon âge, activité et situation de privation d’emploi, y compris démission-reconversion dans ses conditions. La suppression du circuit de refus améliore l’accès futur sans retirer les exceptions favorables ou recours des décisions antérieures.', ['Supprime la condition restrictive et les transmissions propres aux deux refus de CDI après CDD ou mission.'])
b=by['R5312-38']['source_xml'];old='<p>4° sexies Les échanges d\'informations et de données entre l\'opérateur France Travail et les employeurs, ainsi que l\'information des salariés prévus aux articles L. 1243-11-1 et L. 1251-33-1 ;</p>';assert old in b
b=b.replace(old,'<p>4° sexies Pour les seuls faits antérieurs demeurant légalement pertinents, le traitement des informations régulièrement reçues sur le fondement des anciennes dispositions des articles L. 1243-11-1 et L. 1251-33-1, dans la mesure nécessaire aux droits de rectification, aux réclamations et aux contentieux correspondants. Aucun échange nouveau de signalement ou collecte périodique de refus n’est autorisé par cette finalité après la réforme ;</p>')
put('R5312-38',b,'Supprime la finalité de collecte des nouveaux refus de CDI et réserve les données déjà reçues aux droits et litiges anciens. Les autres finalités et responsables de traitement sont conservés.','Allocations, lutte contre le non-recours, droits sociaux, accompagnement, formation et protections des données demeurent. La restriction du seul circuit de refus supprimé ne prive aucun demandeur de son dossier ni de ses recours, et ne crée pas un fichier de remplacement.', ['Retire la finalité permanente de signalement des refus de CDI par les employeurs après CDD ou mission.'])
b=by['R5312-42']['source_xml'];old='b) Les données relatives aux refus de contrats à durée indéterminée en application des articles L. 1243-11-1 et L. 1251-33-1 ;';assert old in b
b=b.replace(old,'b) Pour les seuls dossiers de faits antérieurs mentionnés au 4° sexies du II de l’article R. 5312-38, les données de refus de contrat déjà régulièrement recueillies, dans la mesure nécessaire à la rectification et aux réclamations ou contentieux demeurés ouverts. Aucune donnée de refus nouveau n’est enregistrée sur ce fondement ;')
put('R5312-42',b,'Retire la collecte future de données sur les refus de CDI, tout en conservant les données des dossiers anciens nécessaires aux droits et toutes les autres catégories dans leurs finalités.','Les données d’identité, allocations, handicap, aides, fiscalité, formation, famille et accompagnement restent dans leur champ de nécessité. L’interdiction de cibler les contrôles avec les autres membres du foyer RSA est maintenue ; aucun avantage ni droit de rectification ne disparaît.', ['Supprime la catégorie de données des nouveaux refus de CDI, devenue sans finalité après abrogation du circuit.'])
# Trois parcours IAE : période éligible/accompagnement distincte du contrat, toutes différences sources conservées.
for n,actor,self_prescribe,wide in [('L5132-5','entreprises d’insertion',True,False),('L5132-11-1','associations intermédiaires',False,True),('L5132-15-1','ateliers et chantiers d’insertion, quel que soit leur statut juridique',True,True)]:
 b=f'<p>Les {actor} emploient sous contrat unique sans terme des personnes sans emploi rencontrant des difficultés sociales et professionnelles particulières. Leur parcours d’insertion et l’éligibilité aux aides qui lui sont attachées demeurent régis par leurs conditions propres.</p>'
 b+='<p>Pendant l’exécution du contrat, une ou plusieurs conventions conclues en vertu de l’article L. 5135-4 peuvent prévoir une période de mise en situation en milieu professionnel auprès d’un autre employeur, dans les conditions du chapitre V du présent titre.</p>'
 b+='<p>Le parcours spécifique d’accompagnement est organisé pour une période initiale d’au moins quatre mois, sauf pour les personnes condamnées bénéficiant d’un aménagement de peine. Ses périodes peuvent être poursuivies dans la limite totale de vingt-quatre mois, sans renouveler ni mettre à terme le contrat de travail. Ces durées s’appliquent à l’organisation du parcours et aux aides dans les conditions qui leur sont propres ; elles ne garantissent pas une aide dont les autres conditions ne sont pas remplies.</p>'
 b+='<p>La période peut être prolongée au-delà de cette limite pour achever une action de formation professionnelle déjà en cours, sans dépasser le terme de cette action.</p>'
 decision='un prescripteur mentionné à l’article L. 5132-3'
 if self_prescribe:decision+=' ou, en cas de recrutement direct, la structure qui emploie le salarié'
 b+=f'<p>Une prolongation exceptionnelle du parcours peut être accordée par {decision}, après examen de la situation du salarié au regard de l’emploi, de la capacité contributive de l’employeur et des actions d’accompagnement et de formation déjà conduites :</p>'
 b+='<p>a) Pour les salariés âgés d’au moins cinquante ans ou reconnus travailleurs handicapés qui rencontrent des difficultés particulières faisant obstacle à leur insertion durable dans l’emploi ;</p>'
 if wide:b+='<p>b) Pour les salariés rencontrant des difficultés particulièrement importantes dont l’absence de prise en charge ferait obstacle à leur insertion professionnelle, par décisions successives d’au plus un an et dans la limite de soixante mois.</p>'
 exception='sauf en cas de cumul avec un autre contrat à temps partiel afin d’atteindre un temps plein ou une durée globale au moins égale à celle de l’article L. 3123-27'
 if n=='L5132-15-1':exception='sauf lorsque le contrat le prévoit pour tenir compte des difficultés particulièrement importantes du salarié, ou en cas de cumul avec un autre contrat à temps partiel afin d’atteindre un temps plein ou une durée globale au moins égale à celle de l’article L. 3123-27'
 b+=f'<p>La durée hebdomadaire du travail ne peut être inférieure à vingt heures, {exception}. Elle peut varier sur tout ou partie de la période d’accompagnement sans dépasser la durée légale hebdomadaire. Les périodes travaillées permettent de valider des trimestres d’assurance vieillesse dans les conditions de l’article L. 351-2 du code de la sécurité sociale.</p>'
 b+='<p>À la demande du salarié, le contrat peut être suspendu :</p><p>1° En accord avec l’employeur, pour effectuer une période de mise en situation en milieu professionnel selon le chapitre V ou une action concourant à son insertion professionnelle ;</p><p>2° Pour accomplir l’essai d’un autre emploi sous contrat unique ou, à titre transitoire, d’un CDD déjà conclu avant la réforme et d’une durée d’au moins six mois.</p>'
 b+='<p>En cas d’embauche à l’issue de cette mise en situation, de cette action ou de cet essai, le salarié peut quitter l’emploi d’insertion sans préavis. Il peut également quitter cet emploi pour suivre une formation conduisant à une qualification de l’article L. 6314-1, selon les règles de préavis applicables au contrat unique et sous réserve des dispenses plus favorables légalement applicables.</p>'
 b+='<p>Un décret fixe les conditions de dérogation à la durée hebdomadaire minimale prévue au présent article. Les données à jour de l’accompagnement déjà légalement détenues sont réutilisées pour ces décisions ; aucun dossier identique de renouvellement du contrat de travail n’est exigé.</p>'+transition()
 put(n,b,'Remplace le CDD d’insertion et ses renouvellements par un contrat unique ; les durées initiales/maximales et prolongations deviennent celles du parcours éligible, sans échéance de l’emploi ni perte d’aide. Supprime les avenants de renouvellement à terme et réutilise les pièces d’accompagnement.','Le minimum spécial de vingt heures et ses exceptions sont conservés, ainsi que pension, mise en situation, départ sans préavis après embauche et formation. Les prolongations pour formation, âge/handicap'+(' et grandes difficultés dans la limite de soixante mois'if wide else '')+' restent accessibles aux futurs bénéficiaires ; le décideur conserve le champ propre à la source.', ['Supprime le support CDD, ses renouvellements contractuels et son terme automatique à la fin du parcours d’insertion.'])
# Sécurité de mise à disposition : objet dangereux, dérogations conservées.
put('R5132-22','<p>Le préfet peut résilier la convention conclue avec l’État lorsque l’association intermédiaire réalise des mises à disposition pour des travaux particulièrement dangereux figurant sur la liste de l’article D. 4154-1, en méconnaissance des interdictions et dérogations légalement applicables, ou ne respecte pas les conditions de mise à disposition prévues à l’article L. 5132-9.</p><p>La suppression du support CDD ne supprime ni cette protection liée aux travaux ni les dérogations légalement accordées dans leur champ. Aucune autorisation nouvelle de contrat à terme ne résulte de ces dérogations.</p>','Rend autonome la référence à la nature des travaux dangereux et maintient la résiliation pour manquement effectif, sans supprimer les dérogations ni réintroduire le CDD.','La protection contre les risques graves reste celle de la mise à disposition, avec la liste existante et toutes dérogations légales. La réforme n’ajoute ni nouvelle liste ni dossier d’autorisation de CDD, et les autres conditions de L5132-9 restent entières.')
# Garantie des rémunérations et créances anciennes.
put('L3253-3','<p>Les rémunérations mentionnées au premier alinéa de l’article L. 3253-2 comprennent :</p><p>1° Les salaires, appointements et commissions proprement dits ;</p><p>2° Les accessoires, notamment l’indemnité compensatrice de l’article L. 1226-14, l’indemnité compensatrice de préavis de l’article L. 1234-5, les primes de fin de CDD antérieur demeurées dues selon l’ancien article L. 1243-8 et l’article L. 1241-1, ainsi que l’indemnité de fin de mission de l’article L. 1251-32 dans le champ où elle reste due.</p><p>La suppression des nouveaux CDD ne retire pas aux créances des anciens contrats cette protection. Les indemnités légalement dues au titre du contrat unique demeurent prises en compte selon leur nature et les dispositions régissant leur garantie.</p>','Préserve le privilège des créances salariales et primes des anciens contrats après abrogation du support CDD, sans transformer le nouveau barème ordinaire en plafond des autres rémunérations.','Salaires, accessoires, préavis, inaptitude professionnelle et primes anciennes restent couverts dans leur régime. Aucune créance déjà née n’est déclassée du seul fait du changement de contrat ; les exceptions aux primes de mission restent régies par leurs dispositions propres.')
# Départs favorables CAE/CIE : pas de nouveau CDD permis ; anciennes embauches restent possibles sous transition.
for n,kind,order in [('L5134-28','contrat d’accompagnement dans l’emploi',False),('L5134-70','contrat initiative-emploi',True)]:
 first='D’être embauché dans un emploi sous contrat unique ;';second='D’être embauché au titre d’un CDD conclu avant la réforme, d’une durée d’au moins six mois ;'
 if order:first,second=second,first
 b=f'<p>Le salarié titulaire d’un {kind} peut rompre ce contrat à son initiative pour :</p><p>1° {first}</p><p>2° {second}</p><p>3° Suivre une formation conduisant à une qualification prévue à l’article L. 6314-1.</p><p>Cette faculté s’exerce selon les règles de préavis du contrat unique, sans préjudice des dispenses plus favorables applicables à l’issue d’une période de mise en situation, d’une action d’insertion ou d’un essai. Pour les contrats antérieurs, les conditions protectrices de rupture prévues par l’ancienne loi restent applicables selon l’article L. 1241-1. Aucun nouveau contrat à terme n’est autorisé par le 1° ou le 2°.</p>'
 put(n,b,'Coordonne les départs pour autre emploi ou qualification avec le contrat unique, conserve les embauches CDD antérieurement conclues et n’étend pas la réforme à une suppression des dispenses favorables.','L’accès à un autre emploi ou à une formation qualifiante reste ouvert. Les dispenses de préavis déjà prévues par le dispositif et les droits de rupture des anciens contrats ne sont pas remplacés par une obligation de rester jusqu’à la fin de l’aide.')
# CAE et CIE sont des régimes d’aide d’un seul emploi sans terme.
put('L5134-24','<p>Le contrat de travail associé à l’aide à l’insertion professionnelle attribuée au titre du contrat d’accompagnement dans l’emploi est un contrat unique de droit privé sans terme. Il porte sur des emplois répondant à des besoins collectifs non satisfaits.</p><p>Il ne peut être conclu pour pourvoir des emplois dans les services de l’État.</p><p>L’aide et l’accompagnement sont attribués pour leurs périodes éligibles propres ; leur fin ne rompt pas le contrat. Les anciens contrats à terme restent régis par l’article L. 1241-1 et les droits d’aide ne sont pas supprimés par leur conversion.</p>','Supprime le choix du support CDD dans le CAE et sépare la durée d’aide de la durée de l’emploi, sans modifier la finalité ni l’exclusion des services de l’État.','Les employeurs et salariés éligibles conservent le dispositif CAE dans ses conditions ; l’aide ne devient pas un terme d’emploi. Les droits anciens, aides et possibilités de prolongation favorables demeurent applicables à leurs périodes propres.', ['Supprime la faculté de conclure le CAE comme nouveau CDD au lieu d’un emploi sans terme.'])
put('L5134-25','<p>La période initiale d’accompagnement associée au contrat d’accompagnement dans l’emploi est d’au moins six mois, ou de trois mois pour une personne condamnée bénéficiant d’un aménagement de peine. Elle est distincte de la durée du contrat unique, qui ne comporte pas de terme.</p><p>La poursuite de l’aide ou de l’accompagnement n’est pas soumise à un nombre maximal de renouvellements de CDD ni à la conclusion d’avenants fixant un nouveau terme d’emploi. Ses plafonds et prolongations sont ceux des dispositions qui régissent l’aide.</p><p>Les anciens contrats et leurs durées minimales restent gouvernés par l’article L. 1241-1. La présente période d’accompagnement n’interdit pas une rupture du contrat unique dans ses conditions légales et n’institue pas de remboursement d’aide nouveau.</p>','Remplace la durée minimale du CDD par celle de l’accompagnement éligible et retire toute formalité de renouvellement de l’emploi, sans créer un minimum d’emploi empêchant la rupture légale.','La durée réduite de trois mois en cas d’aménagement de peine reste accessible, comme la dispense de plafond du nombre de prolongations de l’accompagnement dans les limites propres à l’aide. Les anciens termes ne sont pas écourtés.', ['Supprime le support à terme et les formalités de renouvellement CDD du CAE pour les nouvelles embauches.'])
put('L5134-69','<p>Le contrat initiative-emploi est un contrat unique de travail de droit privé sans terme.</p><p>La durée d’attribution ou de prolongation de l’aide à l’insertion professionnelle reste régie par ses dispositions propres. Elle n’est pas soumise aux anciennes limites du nombre de renouvellements CDD et n’entraîne pas la conclusion d’un nouvel avenant à terme ; sa fin ne rompt pas l’emploi.</p>'+transition(),'Supprime le support CDD du CIE en maintenant son régime d’aide et la dispense des limites de renouvellements sur les seules périodes éligibles, sans terme d’emploi.','Le CIE demeure accessible aux bénéficiaires et employeurs éligibles et conserve aides, prolongations et autres dispenses. Aucun plafond d’aide, seuil ou taux nouveau n’est fixé ; les créances anciennes restent protégées.', ['Retire la faculté de CDD dans le CIE et les avenants de renouvellement d’un emploi à terme.'])
# Adultes-relais : choix spécifique confirmé par le parent, indemnité10% réservée aux anciens contrats.
put('L5134-103','<p>Le contrat relatif aux activités d’adultes-relais est un contrat unique de travail de droit privé sans terme.</p><p>Les collectivités territoriales et les autres personnes morales de droit public mentionnées à l’article L. 5134-101 peuvent recourir à ce contrat dans les conditions de la présente section. La restriction qui les obligeait, hors établissements publics industriels et commerciaux, à conclure un CDD est supprimée.</p><p>La période d’essai des nouveaux contrats est celle du régime commun du contrat unique, sans renouvellement autorisé sur le fondement du présent article. Les périodes éligibles de la convention d’aide restent régies par leurs dispositions propres et ne constituent pas un terme d’emploi.</p>'+transition(),'Remplace tous les supports adultes-relais par le contrat unique, supprime l’obligation publique de CDD et l’essai spécial renouvelable. Les périodes de convention et d’aide restent distinctes.','L’accès des employeurs publics et privés au dispositif et à son aide demeure ; aucun contrat n’est rompu automatiquement à la fin d’une période aidée. Les anciens essais plus courts, termes et droits restent protégés ; la nouvelle orientation applique aux nouveaux contrats le régime ordinaire de rupture.', ['Supprime l’obligation de CDD pour les employeurs publics et l’autorisation de renouveler l’essai spécial des nouveaux adultes-relais.'])
put('L5134-104','<p>Les nouveaux contrats uniques relatifs aux activités d’adultes-relais peuvent être rompus dans les conditions communes du contrat unique. L’expiration d’une période annuelle d’aide ne constitue pas une fin de l’emploi ni une faculté distincte de rupture patronale sans motif.</p><p>Pour les contrats conclus avant la réforme, les anciennes facultés de rupture à l’expiration d’une période annuelle demeurent applicables : initiative du salarié avec préavis de deux semaines, ou initiative patronale justifiée par une cause réelle et sérieuse avec les procédures et préavis alors exigés. Les autres causes légales de rupture de ces anciens contrats et leurs garanties ne sont pas supprimées.</p><p>Les créances de l’ancienne indemnité spéciale et les réparations d’une rupture irrégulière restent distinctes du barème ordinaire du nouveau contrat, selon les articles L. 5134-106 et L. 5134-107.</p>','Supprime la rupture annuelle spéciale des nouveaux adultes-relais ; réserve aux anciens contrats la garantie du terme, les deux semaines favorables du salarié et les procédures antérieures.','Les contrats antérieurs conservent leur faculté annuelle et leurs préavis protecteurs ; aucune fin d’aide ne devient licenciement automatique. Les nouveaux contrats suivent la direction spécifique du barème ordinaire, sans effacer motif valable, droits essentiels ou réparations.', ['Supprime le régime annuel distinct de rupture des nouveaux contrats adultes-relais, désormais sans terme.'])
put('L5134-106','<p>Le salarié dont le contrat relatif aux activités d’adultes-relais a été conclu avant la réforme et est rompu par l’employeur dans les conditions annuelles maintenues par l’article L. 5134-104 conserve l’indemnité spéciale de l’ancienne loi.</p><p>Cette indemnité est égale à dix pour cent de la rémunération retenue. Son assiette ne peut excéder la rémunération perçue au titre des dix-huit derniers mois d’exécution du contrat. Le renvoi à l’ancienne prime de fin de CDD sert uniquement à maintenir ce taux et ne rétablit pas le CDD.</p><p>Les nouveaux contrats uniques sont soumis à l’indemnité ordinaire de rupture du régime commun et ne relèvent pas de cette indemnité spéciale annuelle. Les salaires, congés et réparations d’une rupture illégale ne sont pas limités par cette distinction.</p>','Rend autonome le taux10% et son assiette18mois pour les anciens adultes-relais, sans l’effacer avec L1243-8. Direction spécifique confirmée : nouveaux contrats au barème ordinaire, sans extension de la rupture annuelle spéciale.','L’indemnité spéciale des anciens contrats demeure due dans ses conditions, avec son assiette et son taux. Elle n’est pas rétroactivement plafonnée à six mois ni soumise à la franchise d’un an. Les nouveaux contrats suivent le choix de réforme expressément confirmé, sans suppression des réparations d’illégalité.')
put('L5134-107','<p>Pour les contrats d’adultes-relais conclus avant la réforme, la méconnaissance par l’employeur des règles de rupture de l’ancienne sous-section ouvre droit au salarié à des dommages et intérêts correspondant au préjudice subi.</p><p>Cette réparation demeure également ouverte lorsque la rupture résulte du non-respect de la convention de l’article L. 5134-101 qui a entraîné sa dénonciation.</p><p>Pour les contrats uniques nouveaux, les règles communes de réparation de la rupture illégale s’appliquent ; la méconnaissance de la convention ne dispense pas de motif valable ni des protections essentielles. Aucun préjudice déjà réparable ni créance ancienne n’est effacé par la suppression du support CDD.</p>','Retire le renvoi de dérogation au CDD, préserve les réparations des anciens adultes-relais et coordonne les nouveaux contrats avec leurs recours communs.','Le salarié garde la réparation du préjudice subi en cas d’irrégularité ou de dénonciation de convention imputable à l’employeur. Le zéro d’indemnité ordinaire ne devient pas une immunité pour rupture illégale et les recours anciens sont conservés.')
put('L5134-115','<p>Le contrat de travail associé à un emploi d’avenir est un contrat unique sans terme.</p><p>La période initiale d’accompagnement et d’éligibilité au dispositif est de trente-six mois. En cas de circonstances particulières tenant à la situation ou au parcours du bénéficiaire ou au projet associé à l’emploi, elle peut être inférieure, sans être inférieure à douze mois ; elle peut ensuite être portée à trente-six mois, sans renouvellement du contrat de travail.</p><p>Dans le cas du dernier alinéa de l’article L. 5134-113, les personnes mentionnées aux 1° et 2° de l’article L. 5134-19-1 peuvent prolonger cette période pour achever la formation concernée, sans en dépasser le terme.</p><p>La fin d’une période ou de l’aide ne rompt pas le contrat unique, dont la rupture demeure soumise à ses règles propres. Les contrats antérieurs conservent les garanties de terme, les anciennes facultés annuelles et leurs préavis, ainsi que leurs créances, selon l’article L. 1241-1.</p><p>Le bénéficiaire dont l’emploi prend fin à l’issue de sa période dans le dispositif conserve, pendant l’année suivante, une priorité d’embauche : l’employeur l’informe des emplois disponibles compatibles avec sa qualification ou ses compétences. S’il est ainsi recruté, il est dispensé de période d’essai. Les droits acquis au titre de l’ancien contrat demeurent également garantis.</p>','Distingue l’emploi sans terme et la période de l’emploi d’avenir ; conserve12/36mois, prolongation de formation, priorité de réemploi et dispense d’essai, sans nouveau CDD ni renouvellement contractuel.','Le parcours de formation et l’aide restent dans leurs conditions propres ; la priorité d’un an et la dispense d’essai restent accessibles aux futurs bénéficiaires qui cessent d’être employés à l’issue de cette période. Les anciens termes, préavis annuels et créances sont protégés.', ['Supprime le support CDD de12à36mois et sa faculté de renouvellement, remplacés par une période d’accompagnement indépendante de l’emploi.'])
# Formalités simplifiées : conservation effective des dispenses, y compris nouvelles embauches sans terme.
put('L1272-4','<p>Pour les associations et fondations qui l’utilisent, le chèque-emploi associatif vaut accomplissement de l’ensemble des formalités liées à l’embauche et à l’emploi de leurs salariés, notamment :</p><p>1° La déclaration préalable à l’embauche prévue à l’article L. 1221-10 ;</p><p>2° L’inscription au registre unique du personnel prévue à l’article L. 1221-13 ;</p><p>3° L’établissement de l’écrit, l’inscription des mentions légalement requises et leur remise au salarié pour le contrat unique ; pour les CDD antérieurs, les formalités des anciens articles L. 1242-12 et L. 1242-13 encore applicables ;</p><p>4° Pour les contrats à temps partiel, l’écrit et les mentions obligatoires de l’article L. 3123-6 ;</p><p>5° Les déclarations de médecine du travail et du régime des prestations de revenu de remplacement de l’article L. 5421-2.</p><p>Les mêmes données nécessaires ne sont pas communiquées une seconde fois du seul fait du changement de nom du contrat. Les éléments destinés au salarié lui sont remis ; la simplification ne dispense pas des règles de fond ni du volume contractuel garanti.</p>','Étend explicitement la fiction de formalités au contrat unique en conservant la simplification des anciens CDD et du temps partiel ; retire la double communication de données.','Le bénéfice du chèque associatif reste accessible pour les nouveaux contrats sans terme ; l’abrogation des formalités CDD ne provoque pas un nouveau formulaire. La remise au salarié et les garanties de volume du projet antérieur de temps partiel sont préservées.')
put('L1273-5','<p>L’employeur qui utilise le Titre Emploi-Service Entreprise et remet au salarié et envoie à l’organisme habilité les éléments respectivement destinés à chacun est réputé avoir accompli :</p><p>1° Les règles d’établissement du contrat prévues à l’article L. 1221-1 ;</p><p>2° La déclaration préalable à l’embauche de l’article L. 1221-10 ;</p><p>3° La délivrance du certificat de travail de l’article L. 1234-19 ;</p><p>4° Les obligations légalement maintenues d’écrit, de mentions et de remise du contrat unique, et, pour les CDD antérieurs, celles des anciens articles L. 1242-12 et L. 1242-13 ;</p><p>5° Pour le temps partiel, les obligations d’écrit et de mentions de l’article L. 3123-6.</p><p>Les données déjà remises ou transmises à jour ne sont pas ressaisies dans un second formulaire identique. Les règles de fond du contrat, la remise des éléments au salarié et le volume contractuel garanti demeurent applicables.</p>','Préserve pour le contrat unique les dispenses TESE et les deux transmissions essentielles ; supprime les formulaires répétés et garde le temps partiel antérieurement coordonné.','La simplification TESE reste ouverte aux futures embauches sans perdre les anciens droits. Le salarié reçoit toujours ses éléments et son certificat ; la dispense de doubles formulaires ne supprime ni salaire ni volume de travail garanti.')
put('L1271-5','<p>Pour les emplois dont la durée de travail n’excède pas trois heures par semaine au cours d’une période de référence de quatre semaines, l’employeur et le salarié qui utilisent le chèque emploi-service universel sont réputés satisfaire aux obligations légalement maintenues d’établissement, de mentions et de remise du contrat unique, à celles de l’article L. 3123-6 pour le temps partiel ou des articles L. 741-2 et L. 741-9 du code rural et de la pêche maritime. La même dispense couvre les formalités des anciens articles L. 1242-12 et L. 1242-13 pour les CDD antérieurs qui y restent soumis.</p><p>L’obligation de l’article L. 1221-5-1 ne s’applique pas à ces emplois.</p><p>Pour une durée supérieure, le contrat est établi par écrit. Les données légalement recueillies par le CESU et remises au salarié sont réutilisées ; aucune saisie d’un second document identique n’est exigée pour un contrat unique. Le seuil légal de trois heures et la période de quatre semaines ne sont pas modifiés par la réforme.</p>','Conserve la dispense CESU pour les nouvelles relations sans terme, le seuil légal3heures/quatre semaines et l’exception d’information ; évite un écrit/formulaire supplémentaire identique.','La dispense du petit emploi reste disponible aux futurs bénéficiaires et celle du code rural reste entière. Le seuil légal ici distinct du plafond réglementaire du prestataire ponctuel n’est pas supprimé ou élargi par confusion ; le volume garanti du temps partiel reste une règle de fond.')
put('D1272-4','<p>Lorsqu’un contrat de travail a déjà été signé lors de l’embauche dans les conditions des articles L. 1221-1 à L. 1221-5 et, pour le temps partiel, de l’article L. 3123-6, ses clauses remplacent les mentions correspondantes de la déclaration d’identification de l’article D. 133-13-1 du code de la sécurité sociale.</p><p>Cette dispense demeure applicable aux CDD antérieurs qui ont été établis dans les conditions des anciens articles L. 1242-12 et L. 1242-13. Pour le contrat unique comme pour ces contrats antérieurs, aucune seconde saisie de clauses déjà valablement établies et à jour n’est requise ; les seules informations légalement nécessaires manquantes ou modifiées sont complétées.</p>','Conserve la dispense de double déclaration d’identification après établissement du contrat signé et la rend opératoire pour le contrat unique comme les anciens CDD.','Le contrat déjà signé continue de remplacer la déclaration de ses clauses, sans charge nouvelle due à la disparition du CDD. Les garanties de remise et mentions du salarié restent celles du contrat et de D133-13-1 réécrit, sans nouveau dossier d’adhésion.')
# PMSMP et saison : définitions matérielles sans terme d’emploi.
put('L5135-7','<p>Une convention de mise en situation en milieu professionnel ne peut être conclue pour exécuter une tâche régulière d’un poste permanent, faire face à un accroissement temporaire d’activité, remplacer un salarié absent ou dont le contrat est suspendu, ou occuper un emploi saisonnier.</p><p>Pour cette interdiction, est saisonnier l’emploi dont les tâches se répètent chaque année selon une périodicité à peu près fixe, en fonction du rythme des saisons ou des modes de vie collectifs. La suppression du renvoi au CDD ne permet pas d’utiliser une mise en situation à la place d’un emploi salarié.</p>','Autonomise la définition saisonnière et maintient toutes les interdictions de substitution d’un stage d’immersion à un emploi, sans recours au titre CDD abrogé.','L’immersion demeure un outil d’insertion avec ses garanties propres ; elle ne devient pas un moyen d’obtenir un travail gratuit à la place d’un contrat unique. Les droits sociaux et aides de la PMSMP ne sont pas retirés.')
put('L3121-34','<p>Dans les branches saisonnières mentionnées à l’article L. 3132-7, une convention ou un accord d’entreprise ou d’établissement ou, à défaut, une convention de branche ou un accord professionnel ou interprofessionnel peut, dans les conditions déterminées par décret, déroger aux dispositions de la présente section relatives aux périodes de référence du décompte des heures supplémentaires et des repos compensateurs.</p><p>Cette faculté n’est pas subordonnée à la conclusion ou reconduction d’un CDD. L’accord organise des procédures contradictoires de décompte des temps et périodes de travail. Les autres garanties applicables au temps de travail et au repos restent en vigueur.</p>','Conserve la dérogation saisonnière de périodes de référence en supprimant sa dépendance au régime de reconduction CDD. La priorité de l’accord d’entreprise dans cette dérogation et le contradictoire restent.','La faculté d’aménagement reste accessible aux futurs employeurs et salariés saisonniers sous contrat unique ; aucune nouvelle limite de durée n’est créée. Le décompte contradictoire et les repos demeurent protégés sans formulaire de reconduction de l’emploi.', ['Supprime le rattachement de la dérogation saisonnière à un accord de reconduction de CDD désormais impossible.'])
# Travailleurs étrangers : garanties minimales et responsabilité solidaire préservées.
put('L8252-2','<p>Le salarié étranger a droit pour la période d’emploi illicite :</p><p>1° Au salaire et à ses accessoires selon les règles légales, conventionnelles et contractuelles applicables, sous déduction des sommes déjà reçues. Sauf preuve contraire, les sommes correspondent à une relation présumée de trois mois ; le salarié peut prouver par tout moyen la durée réelle du travail ;</p><p>2° En cas de rupture, à une indemnité forfaitaire de trois mois de salaire, sauf si le préavis, l’indemnité de rupture légalement due ou les stipulations contractuelles lui procurent une solution plus favorable. Pour les CDD antérieurs, les créances des anciens articles L. 1243-4 et L. 1243-8 restent comprises dans cette comparaison ;</p><p>3° Le cas échéant, au paiement par l’employeur des frais d’envoi des rémunérations impayées vers le pays où il est parti volontairement ou a été reconduit.</p><p>En cas de travail dissimulé, il bénéficie des dispositions de l’article L. 8223-1 ou du présent chapitre selon celles qui lui sont plus favorables.</p><p>Le conseil de prud’hommes peut accorder par provision l’indemnité forfaitaire du 2°. Le salarié peut demander une réparation supplémentaire s’il prouve un préjudice non réparé.</p><p>La franchise et le plafond de l’indemnité ordinaire du contrat unique ne suppriment ni ce forfait protecteur ni les salaires, congés et réparations distincts, et ne diminuent pas les créances d’un CDD antérieur.</p>','Coordonne les créances d’anciens CDD et du contrat unique sans supprimer le forfait protecteur du travailleur étranger, les solutions plus favorables ou les dommages supplémentaires.','Trois mois présumés de salaire, forfait de trois mois, preuve libre, frais d’envoi, comparaison favorable avec travail dissimulé et provision demeurent. Le zéro ordinaire avant un an ne devient pas zéro réparation de l’emploi illicite.')
put('L8254-2','<p>La personne qui méconnaît l’article L. 8254-1 est tenue solidairement avec son cocontractant, sans préjudice des articles L. 8222-1 à L. 8222-6, de payer :</p><p>1° Le salaire et ses accessoires dus au salarié étranger non autorisé à travailler selon le 1° de l’article L. 8252-2 ;</p><p>2° Les indemnités dues au titre de la rupture selon le 2° de l’article L. 8252-2 ou, si cela est plus favorable, les indemnités légales de préavis et de rupture, les stipulations contractuelles correspondantes et, pour les CDD antérieurs, les créances conservées des anciens articles L. 1243-4 et L. 1243-8 ;</p><p>3° Les frais d’envoi des rémunérations impayées mentionnés au 3° de l’article L. 8252-2 ;</p><p>4° L’amende administrative prévue à l’article L. 8253-1 dans le champ qui lui demeure applicable.</p><p>La suppression du support CDD ne retire aucune créance ancienne de cette solidarité. Le barème ordinaire du contrat unique ne limite pas les droits plus favorables et les protections distinctes du travailleur.</p>','Maintient la solidarité pour toutes les catégories de créances et rend explicite la persistance des dettes CDD antérieures malgré abrogation des renvois futurs.','Salaires, forfait protecteur ou solution plus favorable, frais de retour des sommes et créances anciennes restent garantis. Aucun avantage de prescription ou d’exonération légalement applicable n’est supprimé et aucune amende nouvelle n’est instituée.')
# Garanties juridictionnelles : paragraphes inchangés sauf qualification de la prime ancienne.
b=by['R1454-14']['source_xml'];b=b.replace("e) Le versement de l'indemnité de fin de contrat prévue à l'article L. 1243-8 et de l'indemnité de fin de mission mentionnée à l'article L. 1251-32 ;",'e) Le versement des primes de fin de CDD antérieur demeurées dues selon l’ancien article L. 1243-8 et l’article L. 1241-1, et de l’indemnité de fin de mission de l’article L. 1251-32 dans son champ applicable ;');b+='<p>Ces pouvoirs de provision et de conservation des preuves restent ouverts aux créances du contrat unique et aux créances conservées des contrats antérieurs. La franchise d’indemnité ordinaire ne supprime pas une créance de salaires, congés, inaptitude professionnelle ou réparation ayant un fondement distinct.</p>'
put('R1454-14',b,'Conserve tous les pouvoirs du bureau de conciliation et d’orientation, la preuve et l’attestation provisoire, en maintenant les primes des anciens CDD dans leurs provisions.','Les provisions sur salaires, congés, préavis, inaptitude et primes anciennes restent possibles sans obligation sérieusement contestable. La décision provisoire d’attestation, sa transmission à France Travail et les recours de deux mois demeurent ; aucun droit au juge n’est retiré.')
# Mandats : source intégrale conservée pour les contrats antérieurs, aucune autorisation d'un nouveau CDD.
for n in ['L2412-2','L2412-3','L2412-4','L2412-5','L2412-8','L2412-9','L2412-13']:
 b='<p>Les dispositions du présent article demeurent applicables aux contrats à durée déterminée conclus avant l’entrée en vigueur de la loi instituant le contrat unique, dans les conditions transitoires de l’article L. 1241-1.</p>'+by[n]['source_xml']
 b+='<p>Les renvois aux anciens articles L. 1242-2 et L. 1244-2-2 servent exclusivement à préserver les catégories, droits de reconduction et prolongations de protection attachés à ces contrats antérieurs. Ils n’autorisent aucun nouveau CDD ni renouvellement à terme après la réforme. L’exécution d’un droit de réemploi conservé prend la forme d’un contrat unique sans terme, sans perte de l’ancienneté ou de la protection acquises.</p><p>Les nouveaux contrats uniques restent soumis à la protection des salariés investis d’un mandat prévue au chapitre Ier du présent titre. La fin d’une aide, d’une période d’activité saisonnière ou d’une mission ne crée pas un terme dispensant de cette protection.</p>'
 put(n,b,'Réserve la procédure spéciale de fin de CDD et ses protections saisonnières aux contrats antérieurs ; maintient toutes les catégories, périodes et conditions sources et rattache les nouveaux contrats au statut protecteur commun.','L’autorisation de l’inspecteur, les protections des anciens titulaires/candidats selon les renvois propres de l’article et leur prolongation saisonnière sont intégralement conservées. Aucun mandat n’est perdu par la conversion ni aucune nouvelle faculté de CDD créée. Les protections communes des nouveaux salariés mandatés restent applicables.')
put('L2421-8-1','<p>Pour les contrats saisonniers conclus avant la réforme, l’exception à l’article L. 2421-8 demeure applicable lorsque, par une convention ou un accord collectif étendu ou par le contrat, l’employeur est tenu à l’arrivée du terme de reconduire le contrat pour la saison suivante.</p><p>Le caractère saisonnier est celui des tâches appelées à se répéter chaque année selon une périodicité à peu près fixe, en fonction du rythme des saisons ou des modes de vie collectifs. Cette exception conserve son champ et ne permet pas de renouveler un CDD après la réforme : le droit acquis de réemploi s’exécute sous contrat unique sans terme selon l’article L. 1241-1.</p><p>Les nouveaux contrats uniques ne prennent pas fin à l’issue d’une saison ; leur rupture reste soumise aux protections des salariés mandatés applicables au contrat sans terme.</p>','Conserve l’exception favorable au contrôle de fin de saison lorsque le réemploi est déjà garanti, sans transformer ce droit en autorisation de nouveau CDD.','La dispense existante d’une formalité de fin de terme demeure pour les anciens contrats dans ses conditions exactes : engagement de reconduction par accord étendu ou contrat. Le droit de retour et le statut protecteur restent conservés lors de la conversion.')
# Dérogations au minimum spécial de20heures : accès facilité avec consentement, conditions matérielles/durées conservées.
for n,ref in [('D5132-10-5-3','L. 5132-5'),('D5132-26-12','L. 5132-11-1'),('D5132-43-14','L. 5132-15-1')]:
 b=f'<p>La dérogation à la durée hebdomadaire minimale de vingt heures prévue à l’article {ref}, en cas de cumul avec un autre contrat à temps partiel, peut être mise en œuvre avec l’accord libre du salarié et de son employeur, après examen par la structure d’insertion de sa situation au regard de l’emploi, des actions d’accompagnement et de formation du parcours.</p>'
 b+='<p>Elle ne s’applique pas lorsque l’autre contrat à temps partiel est conclu avec une structure mentionnée aux articles L. 5132-4 ou L. 5213-13 distincte de l’employeur.</p><p>L’autorisation préalable du préfet et l’attente de quatre mois après l’entrée dans le parcours sont supprimées. La dérogation peut être utilisée dès que ses conditions matérielles sont réunies, sans nouvel avenant de renouvellement du contrat à durée déterminée.</p><p>La période de dérogation ne peut excéder six mois. Elle peut être renouvelée une fois, avec l’accord du salarié et de l’employeur, après examen actualisé de ses perspectives d’évolution professionnelle. Les éléments à jour du suivi déjà détenus sont réutilisés ; aucun bilan identique n’est transmis une seconde fois à l’administration.</p><p>Le volume de travail résultant de l’accord est garanti par le contrat ; il ne peut être réduit unilatéralement. Les dérogations déjà accordées conservent leur durée et leurs effets favorables ; la simplification reste ouverte aux nouveaux bénéficiaires du contrat unique.</p>'
 put(n,b,'Supprime l’autorisation préfectorale préalable et les quatre mois d’attente pour la dérogation de cumul, avec consentement du salarié, conditions matérielles et limites de durée conservés.','La possibilité de descendre sous vingt heures reste ouverte aux bénéficiaires actuels et futurs, sans attente administrative ; la limite de six mois renouvelable une fois et l’exclusion du cumul entre structures visées sont conservées. Le volume convenu ne peut être réduit unilatéralement.', ['Supprime l’autorisation préfectorale préalable à une dérogation de cumul librement convenue et justifiée par le parcours.','Supprime le délai administratif de quatre mois avant de pouvoir bénéficier de la dérogation de cumul.','Retire la retransmission d’un bilan identique déjà disponible lors de l’examen de renouvellement.'])
put('D5132-43-5','<p>La dérogation à la durée hebdomadaire minimale de vingt heures dans les ateliers et chantiers d’insertion peut être mise en œuvre après examen de la situation du salarié, avec son accord libre et celui de l’employeur. L’autorisation préalable du préfet n’est plus requise.</p><p>La période de dérogation ne peut excéder douze mois. Elle peut être prolongée après examen de la situation au regard de l’emploi et des actions d’accompagnement et de formation dont le salarié a bénéficié, le cas échéant avec la coopération du préfet et des organismes d’insertion compétents.</p><p>La prolongation a pour objet d’achever les actions d’accompagnement et de formation prescrites initialement ; elle ne peut dépasser la durée de l’action ou de l’atelier et chantier conventionné.</p><p>La démarche peut être engagée par l’employeur avant l’embauche ou par le salarié en accord avec lui. Les données de suivi déjà à jour sont réutilisées ; il n’est exigé ni nouveau dossier identique ni nouvelle autorisation au seul motif de la conversion en contrat unique.</p><p>Le volume de travail accepté est garanti au salarié et ne peut être réduit unilatéralement. Les dérogations antérieures gardent leurs effets favorables et restent disponibles aux futurs bénéficiaires ; leur durée ne fixe pas le terme de l’emploi.</p>','Retire l’autorisation préfectorale préalable d’une dérogation individuelle justifiée et consentie ; conserve douze mois, examen et prolongation finalisée de formation, en réutilisant les pièces.','La dérogation favorable et sa prolongation demeurent ouvertes aux salariés des ateliers et chantiers, avec initiative possible du salarié ou de l’employeur et consentement. Aucun dossier récurrent ni diminution unilatérale du temps garanti ne remplace l’autorisation.', ['Supprime l’autorisation préfectorale préalable à la dérogation individuelle consentie et justifiée.','Supprime la répétition des mêmes pièces de parcours lors du passage au contrat unique.'])
put('D5132-43-8','<p>Lorsqu’un atelier et chantier d’insertion accueille des salariés présentant des difficultés communes particulièrement importantes, l’employeur peut organiser une dérogation à la durée hebdomadaire minimale de vingt heures, avec l’accord libre de chaque salarié concerné.</p><p>L’autorisation préalable du préfet n’est plus requise. L’employeur s’appuie sur les éléments du parcours déjà disponibles qui établissent ces difficultés communes ; aucun dossier identique n’est exigé pour chaque salarié.</p><p>La période de dérogation ne peut dépasser douze mois. Le volume convenu est garanti dans chaque contrat et ne peut être réduit unilatéralement. Les dérogations déjà accordées restent valables dans leurs conditions, et la faculté demeure ouverte aux futurs bénéficiaires du contrat unique sans en fixer le terme.</p>','Supprime l’autorisation préalable de la dérogation collective pour difficultés communes, tout en garantissant consentement individuel, preuve du besoin et maximum de douze mois.','L’accès à la dérogation demeure possible aux nouveaux salariés de l’atelier ou chantier, avec maintien de douze mois et des décisions favorables anciennes. La simplification ne permet pas d’imposer moins d’heures à un salarié sans son accord.', ['Supprime l’autorisation préfectorale préalable pour les dérogations liées à des difficultés communes établies et consenties.'])
put('D5132-26-9','<p>Les personnes âgées d’au moins cinquante-sept ans rencontrant des difficultés sociales et professionnelles peuvent bénéficier du régime d’emploi sans terme prévu à l’article L. 5132-14-1 au sein d’une association intermédiaire, sans attendre douze mois après le début de leur parcours.</p><p>L’association examine leur situation au regard de l’emploi et des actions d’accompagnement et de formation déjà conduites. Elle utilise les éléments à jour du parcours, que celui-ci ait été effectué sous un contrat antérieur à durée déterminée ou sous contrat unique ; aucun CDD préalable n’est requis.</p><p>Lorsque l’emploi existe déjà sous contrat unique, l’accès à ce régime ne nécessite pas une rupture suivie d’une réembauche ni une nouvelle période d’essai. L’ancienneté, les droits acquis et les aides qui restent légalement dues sont conservés dans leurs conditions propres.</p>','Supprime les douze mois d’attente et l’exigence d’un CDD préalable pour accéder au régime des associations intermédiaires à partir de57ans, sans modifier l’âge légal ni créer de taux d’aide.','Le régime favorable reste ouvert aux personnes d’au moins57ans en difficulté, y compris celles entrées directement en contrat unique. La continuité de l’ancienneté et des aides applicables est garantie sans passage artificiel par une rupture ou un CDD.', ['Supprime le délai minimal de douze mois avant l’accès au régime sans terme des personnes âgées d’au moins57ans.','Retire le préalable d’un CDD d’insertion devenu impossible et les formalités de rupture/réembauche qui en résulteraient.'])
put('L5213-13-2','<p>Les entreprises adaptées peuvent employer sous contrat unique les travailleurs mentionnés à l’article L. 5213-13-1 afin de faciliter leur transition professionnelle vers d’autres entreprises.</p><p>Le parcours comporte un accompagnement renforcé pour réaliser le projet professionnel et valoriser les compétences acquises en formation.</p><p>Un décret en Conseil d’État fixe les conditions des périodes d’accompagnement et d’éligibilité aux aides, en tenant compte des actions menées et de la situation du salarié : la période initiale peut atteindre vingt-quatre mois et ses prolongations peuvent porter la durée totale du parcours à soixante mois. Ces périodes ne sont ni la durée totale d’un CDD ni des renouvellements du contrat de travail.</p><p>Le décret peut prévoir les modalités spécifiques favorables de suspension ou de rupture à l’initiative du salarié et les dérogations à la durée hebdomadaire minimale. Elles demeurent accessibles aux futurs bénéficiaires du contrat unique. L’achèvement du parcours ou de l’aide ne rompt pas automatiquement l’emploi ; les anciens contrats et droits acquis sont protégés selon l’article L. 1241-1.</p>','Remplace le CDD tremplin par le contrat unique avec période d’accompagnement distincte, conserve24/60mois et les facultés réglementaires favorables de suspension, départ et temps de travail.','L’accompagnement renforcé et les aides restent accessibles aux travailleurs handicapés éligibles ; les dérogations de durée et de mobilité ne disparaissent pas avec le CDD. Les24/60mois concernent le parcours, sans perte d’ancienneté ni rupture automatique de l’emploi.', ['Supprime le support CDD et les renouvellements de contrat à terme du parcours tremplin en entreprise adaptée.'])
# GUSO : formalités et remise effectivement conservées aux nouvelles embauches, sans nouveau dossier.
put('L7122-24','<p>L’employeur qui remet au salarié et adresse à l’organisme habilité les éléments de la déclaration prévue à l’article L. 7122-23 respectivement destinés à chacun est réputé satisfaire :</p><p>1° À la déclaration préalable à l’embauche de l’article L. 1221-10 ;</p><p>2° À la remise du certificat de travail de l’article L. 1234-19 ;</p><p>3° Aux obligations légalement maintenues d’établissement, de contenu et de remise du contrat unique et à l’information de l’article L. 1221-5-1 ; pour les CDD antérieurs, cette dispense couvre les anciens articles L. 1242-12 et L. 1242-13 ;</p><p>4° À l’affiliation à la caisse de congés payés de l’article L. 3141-32 ;</p><p>5° Aux déclarations des articles 87 et 87-0 A du code général des impôts.</p><p>Les données déjà complètes et à jour du guichet sont réutilisées ; aucun nouveau formulaire identique n’est imposé pour la substitution du contrat unique au CDD. Les remises au salarié et les règles de fond de son emploi restent applicables.</p>','Conserve toutes les fictions de formalités du GUSO pour les emplois sans terme et les anciens CDD, avec remise au salarié et absence de nouvelle déclaration identique.','L’affiliation congés, certificat, information du salarié, déclarations fiscales et dispenses GUSO restent ouvertes aux futures embauches. L’abolition du CDD ne provoque ni perte d’accès au guichet ni double formalité ; le support d’accès L7122-23 est coordonné dans le complément.')
b=by['R7122-18']['source_xml'];b=b.replace('<p>b) Motif du contrat ; </p>','<p>b) Pour les seuls CDD conclus avant la réforme, leur motif selon le régime antérieur ; aucun motif de recours à un CDD n’est requis pour le contrat unique ;</p>');b=b.replace("<p>e) Signature de l'employeur à la date d'expiration du contrat de travail ; </p>",' <p>e) Signature de l’employeur lors de la cessation effective de la relation de travail ; une fin de prestation ou de période déclarée n’est pas à elle seule la fin du contrat unique ;</p>');b=b.replace("<p>f) Les droits du salarié à l'indemnité compensatrice de congés mentionnée à l'article L. 1242-16 et les modalités de service des congés annuels dont bénéficie le salarié ; </p>",'<p>f) Les droits du salarié aux congés annuels et, lorsqu’elle est due, à l’indemnité compensatrice selon le régime commun ; pour les CDD antérieurs, les droits conservés de l’ancien article L. 1242-16 ; les modalités de service des congés restent indiquées ;</p>');b+='<p>Les données stables déjà détenues légalement et à jour sont reprises sans nouvelle saisie. Les données variables de rémunération et de travail restent déclarées ; la simplification ne supprime aucune mention de droit au salaire, congés, formation ou protection sociale. Aucune date de fin de contrat n’est déduite de la seule période d’activité déclarée.</p>'
put('R7122-18',b,'Supprime le motif de recours CDD pour les nouveaux contrats et la confusion entre fin de prestation et fin d’emploi ; maintient toutes les autres rubriques GUSO et les droits de congés.','Les données de salaire, retenue fiscale, formation, régimes sociaux et congés restent complètes. Les droits anciens de congés restent garantis, la réutilisation des coordonnées évite une saisie répétée et la fin d’un cachet ne met pas automatiquement fin à l’emploi.', ['Supprime la rubrique de motif de recours au CDD pour les contrats uniques et la seconde saisie de données stables déjà connues.'])
put('R7122-21','<p>Au plus tard dans les deux jours suivant l’embauche, l’employeur remet au salarié l’exemplaire du second volet de la déclaration unique et simplifiée qui lui est destiné. Ce volet satisfait aux obligations légalement maintenues de forme, de contenu, de remise du contrat unique et d’information prévues à l’article L. 1221-5-1.</p><p>Pour les CDD antérieurs, cette remise conserve son effet au regard des anciens articles L. 1242-12 et L. 1242-13. Aucun second exemplaire contenant les mêmes données n’est exigé du seul fait du passage au contrat unique ; la remise au salarié et le délai de deux jours demeurent.</p>','Maintient le délai et l’exemplaire du salarié dans la formalité GUSO unique, sans écrit supplémentaire lié à la disparition du CDD.','Le salarié reçoit toujours ses informations et la preuve du contrat dans les deux jours. La dispense de document identique reste ouverte aux futures embauches ; les obligations matérielles d’information et les droits anciens ne sont pas supprimés.')
# Assurance chômage : activité saisonnière/d'usage et vendange conservées matériellement.
put('R5422-1','<p>La durée d’attribution de l’allocation prévue à l’article L. 5422-2 ne peut être inférieure à cent quatre-vingt-deux jours calendaires.</p><p>Elle est réduite, le cas échéant, de la durée du contrat de sécurisation professionnelle dont l’intéressé a bénéficié à la fin du même contrat de travail selon l’article L. 1233-65.</p><p>Par dérogation, la durée minimale est de cent cinquante-deux jours calendaires pour les demandeurs d’emploi visés à la seconde phrase de l’article L. 5422-2-2 et pour ceux dont l’affiliation est exclusivement justifiée par l’exercice des activités saisonnières ou d’usage définies au 3° des anciens articles L. 1242-2 et L. 1251-6, ou de travaux de vendanges au sens de l’article L. 718-4 du code rural et de la pêche maritime, lorsqu’ils ont bénéficié d’une modulation des conditions d’activité antérieure permettant l’ouverture ou le rechargement des droits.</p><p>Pour les nouveaux contrats uniques, ces activités restent éligibles à la dérogation dans le même champ matériel ; leur exercice ne nécessite pas un CDD ou un contrat de mission à terme. Les références aux anciens textes servent à identifier les activités et secteurs concernés, sans rétablir leurs règles de durée ou de renouvellement d’emploi. Les travaux de vendanges comprennent leurs préparatifs, leur réalisation et les travaux de rangement. Les contrats antérieurs et affiliations déjà acquis demeurent pris en compte.</p>','Préserve la modulation favorable d’accès aux droits pour les activités saisonnières, d’usage et de vendanges sous contrat unique, sans transformer l’ancien support CDD en condition devenue impossible.','Les182jours ordinaires et152jours dérogatoires restent avec leurs conditions de modulation, sans nouvel abaissement de droits. Les futurs travailleurs des mêmes activités restent éligibles ; les affiliations anciennes et la déduction CSP dans leur champ sont conservées.')
assert set(out)==set(by),(set(by)-set(out))
rows=[out[s['number']]for s in S]
(H/'answer.json.tmp').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n');(H/'answer.json.tmp').replace(H/'answer.json')
